const STORE='hanama-draft-v1';const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
function makeItem(type,options={}){const a=assetById[type];return {id:uid(),type,x:50,y:65,h:a.height||48,angle:0,trim:0,flip:false,length:1,cuts:[],...options};}
const initial=()=>({version:2,id:uid(),title:'风经过的地方',vessel:'round',scene:'paper',mood:'静寂',generation:'natural',intention:'像清晨的风掠过庭院，安静、自然，留一点不完美。',items:[makeItem(specimenFor('pine').id,{h:49,angle:-20}),makeItem(specimenFor('calla').id,{h:45,angle:9}),makeItem(specimenFor('chrysanthemum').id,{h:32,angle:28})]});
const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));const clone=o=>JSON.parse(JSON.stringify(o));const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function validate(v){
 if(!v||![1,2].includes(v.version)||!Array.isArray(v.items)||v.items.length>24||!vessels.some(a=>a.id===v.vessel)||!Object.hasOwn(scenes,v.scene))throw Error('这不是有效的花间草稿');
 let totalPoints=0;
 return {version:2,id:typeof v.id==='string'?v.id.slice(0,80):uid(),title:String(v.title||'未命名作品').slice(0,40),vessel:v.vessel,scene:v.scene,mood:['静寂','侘寂','春意','野趣'].includes(v.mood)?v.mood:'静寂',generation:['natural','creative','faithful'].includes(v.generation)?v.generation:'natural',intention:String(v.intention||'').slice(0,600),items:v.items.map(i=>{
  if(!specimens.some(a=>a.id===i.type)||!['x','y','h','angle','trim'].every(k=>Number.isFinite(i[k])))throw Error('花材信息不完整');
  const cuts=(Array.isArray(i.cuts)?i.cuts:[]).slice(0,24).map(c=>{
   if(!['lasso','brush'].includes(c.kind)||!Array.isArray(c.points)||c.points.length>128)throw Error('剪枝信息不完整');
   totalPoints+=c.points.length;if(totalPoints>8000)throw Error('剪枝信息过多');
   const points=c.points.map(p=>{if(!Array.isArray(p)||p.length!==2||!p.every(Number.isFinite))throw Error('剪枝坐标无效');return p.map(n=>clamp(n,-3,4));});
   return {kind:c.kind,points,radius:clamp(Number.isFinite(c.radius)?c.radius:.025,.002,.3)};
  });
  return makeItem(i.type,{id:uid(),x:clamp(i.x,5,95),y:clamp(i.y,15,95),h:clamp(i.h,10,95),angle:clamp(i.angle,-180,180),trim:clamp(i.trim,0,60),flip:!!i.flip,length:clamp(Number.isFinite(i.length)?i.length:1,.6,2.4),cuts});
 })};
}
let state=initial(),selected=null,category='flowers',familyFilter='all',vesselFilter='all',undoStack=[],redoStack=[],toastTimer,images={},galleryUrls=[],importArtFor=null,drag=null,editMode='move',stroke=null,layerDragId=null;
const spriteCache=new Map();
try{const v=localStorage.getItem(STORE);if(v)state=validate(JSON.parse(v))}catch{}
function bytesToBase64(bytes){let str='';for(let i=0;i<bytes.length;i+=8192)str+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(str)}
async function readLimited(stream,max=500000){const reader=stream.getReader(),parts=[];let size=0;try{for(;;){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>max)throw Error('草稿过大');parts.push(value)}}finally{reader.releaseLock()}const out=new Uint8Array(size);let offset=0;for(const part of parts){out.set(part,offset);offset+=part.length}return out}
async function encodeShare(s){const bytes=new TextEncoder().encode(JSON.stringify(s));if(globalThis.CompressionStream){const encoded=await readLimited(new Blob([bytes]).stream().pipeThrough(new CompressionStream('gzip')));return '#draft2='+bytesToBase64(encoded).replaceAll('+','-').replaceAll('/','_').replaceAll('=','')}return '#draft='+bytesToBase64(bytes)}
async function decodeShare(hash){const compressed=hash.startsWith('#draft2=');let data=hash.slice(compressed?8:7);if(data.length>30000)throw Error('草稿链接过长');if(compressed)data=data.replaceAll('-','+').replaceAll('_','/');let bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));if(compressed){if(!globalThis.DecompressionStream)throw Error('请通过草稿文件导入');bytes=await readLimited(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip')))}return validate(JSON.parse(new TextDecoder().decode(bytes)))}
let sharedLoaded=false;
try{if(location.hash.startsWith('#draft=')||location.hash.startsWith('#draft2=')){state=await decodeShare(location.hash);state.id=uid();sharedLoaded=true;history.replaceState(null,'',location.pathname+location.search)}}catch{setTimeout(()=>toast('草稿链接无法打开，请用导出的 JSON 文件恢复。'),500)}
selected=state.items.at(-1)?.id||null;

function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));$('#save-state').textContent='已自动保存到本机'}catch{$('#save-state').textContent='本机保存不可用，请导出草稿'}}
function checkpoint(){undoStack.push({state:clone(state),selected});if(undoStack.length>60)undoStack.shift();redoStack=[];renderHistory()}
function renderHistory(){$('#undo-button').disabled=!undoStack.length;$('#redo-button').disabled=!redoStack.length}
function current(){return state.items.find(i=>i.id===selected)}
function specimenCanvas(item,extraCut){
 const key=JSON.stringify([item.type,item.length,item.trim,item.cuts]);
 if(!extraCut&&spriteCache.get(item.id)?.key===key)return spriteCache.get(item.id).canvas;
 if(!images[item.type])return null;
 const canvas=composeSpecimen(images[item.type],item,assetById[item.type],extraCut);
 if(!extraCut)spriteCache.set(item.id,{key,canvas});return canvas;
}
function stemStyle(i){const a=assetById[i.type],g=dimensions(i,a);return `left:${i.x}%;top:${i.y}%;height:${i.h*g.height}%;width:${i.h*g.ratio}%;--anchor:${g.anchor*100}%;transform-origin:${g.anchor*100}% 100%;transform:translate(${-g.anchor*100}%,-100%) rotate(${i.angle}deg) scaleX(${i.flip?-1:1});`}
function drawStemCanvas(el,item,extraCut){const src=specimenCanvas(item,extraCut);if(!src)return;const canvas=$('canvas',el);canvas.width=src.width;canvas.height=src.height;canvas.getContext('2d').drawImage(src,0,0)}
function renderStage(){
 const root=$('#composition');root.innerHTML=state.items.map(i=>`<div class="stem ${i.id===selected?'selected':''}" data-id="${i.id}" style="${stemStyle(i)}" role="button" tabindex="0" aria-label="${assetById[i.type].name}，点击选择，拖动调整" aria-pressed="${i.id===selected}"><canvas class="specimen-image" aria-hidden="true"></canvas></div>`).join('');
 for(const i of state.items){drawStemCanvas($(`.stem[data-id="${i.id}"]`),i)}
 for(const id of spriteCache.keys()){if(!state.items.some(i=>i.id===id))spriteCache.delete(id)}
 $('#vessel').src=assetPath(state.vessel);$('#vessel').alt=assetById[state.vessel].name;const vg=vesselGeometry(assetById[state.vessel]);$('#vessel').style.height=vg.height+'%';$('#vessel').style.width=vg.width+'%';$('#stage').dataset.scene=state.scene;
 $$('[data-scene]').forEach(b=>b.classList.toggle('active',b.dataset.scene===state.scene));$('#study-count').textContent=String(state.items.length).padStart(3,'0');renderSelection();renderHistory();renderLayerList();drawPruneOverlay();
}
function renderSelection(){
 let i=current();$('#selected-empty').hidden=!!i;$('#selection-controls').hidden=!i;if(!i){setEditMode('move');return;}
 const a=assetById[i.type];$('#selected-thumb').src=assetPath(i.type);$('#selected-thumb').alt=a.name;$('#selected-name').textContent=a.name;$('#variant-label').textContent=`${a.color} · ${a.pose}`;
 $('#angle').value=i.angle;$('#size').value=i.h;$('#trim').value=i.trim;$('#length').value=Math.round((i.length??1)*100);
 $('#angle-value').value=i.angle+'°';$('#size-value').value=Math.round(i.h/a.height*100)+'%';$('#trim-value').value=i.trim+'%';$('#length-value').value=Math.round((i.length??1)*100)+'%';$('#restore-cuts').disabled=!i.cuts?.length;
}
const generationDescriptions={natural:'逐枝重建不同的曲线、花面和疏密，再用统一窗光自然成像。',creative:'把双参考图当作灵感，允许更明显地调整疏密、花面与线条。',faithful:'保留主要布局与留白，但重新生长枝叶并统一真实光影。'};
function renderAll(){renderStage();renderMaterials();$('#work-title').value=state.title;$('#intention').value=state.intention;$$('[data-mood]').forEach(b=>b.classList.toggle('active',b.dataset.mood===state.mood));$('#generation-mode').value=state.generation||'natural';$('#generation-mode-help').textContent=generationDescriptions[state.generation||'natural'];persist()}
function addSpecimen(type,placement='front'){if(state.items.length>=24)return toast('先让这 24 枝找到自己的位置，再添加。');checkpoint();const insertion=vesselGeometry(assetById[state.vessel]).insertion,item=makeItem(type,{x:insertion[0],y:insertion[1],angle:0});if(placement==='back')state.items.unshift(item);else state.items.push(item);selected=item.id;setEditMode('move');renderStage();persist();toast(`添入一枝${assetById[type].name}，放在${placement==='back'?'最后层':'最前层'}`)}
function variantPicker(family,replaceId=null){
 const options=specimens.filter(a=>a.family===family).sort((a,b)=>Number(legacyFlowers.includes(a))-Number(legacyFlowers.includes(b)));
 const selectedType=state.items.find(i=>i.id===replaceId)?.type;
 let placement='front';
 const placementChoice=replaceId?'':`<fieldset class="insert-position"><legend>加入画布的位置</legend><button type="button" class="active" data-insert-position="front" aria-pressed="true"><strong>最前层</strong><small>盖在现有花材前</small></button><button type="button" data-insert-position="back" aria-pressed="false"><strong>最后层</strong><small>藏在现有花材后</small></button></fieldset>`;
 openModal(`<h2>${esc(options[0].name)}，选一枝喜欢的。</h2><p>选择自然花色与花面姿态。整枝的倾斜角度仍可在画布里自由调整。</p>${placementChoice}<div class="variant-grid">${options.map(a=>`<button class="variant-card ${a.id===selectedType?'active':''}" data-variant="${a.id}"><img src="${assetPath(a.id)}" alt="${esc(a.color+' '+a.pose)}"><strong><i style="background:${a.swatch}"></i>${esc(a.color)}</strong><span>${esc(a.pose)}</span></button>`).join('')}</div>${replaceId&&current()?.cuts.length?'<p class="file-note">换姿态会恢复这枝的剪口，便于重新修剪；可以撤销恢复。</p>':''}`,'BOTANICAL VARIATIONS');
 $$('[data-insert-position]').forEach(b=>b.onclick=()=>{placement=b.dataset.insertPosition;$$('[data-insert-position]').forEach(t=>{const on=t===b;t.classList.toggle('active',on);t.setAttribute('aria-pressed',String(on))})});
 $$('[data-variant]').forEach(b=>b.onclick=()=>{if(replaceId){const i=state.items.find(i=>i.id===replaceId);if(!i)return;if(i.type!==b.dataset.variant){checkpoint();i.type=b.dataset.variant;i.cuts=[];spriteCache.delete(i.id);selected=i.id;renderStage();persist()}}else addSpecimen(b.dataset.variant,placement);$('#modal').close()});
}
$('#change-variant').onclick=()=>{const i=current();if(i)variantPicker(assetById[i.type].family,i.id)};
function renderMaterials(){
 const materials=category==='flowers'?flowers.filter(a=>familyFilter==='all'||a.group===familyFilter):vessels.filter(a=>vesselFilter==='all'||a.group===vesselFilter);
 $('#material-filters').hidden=category!=='flowers';$('#vessel-filters').hidden=category!=='vessels';$('#material-heading').textContent=category==='flowers'?'一枝一叶':'一器一境';$('#material-count').textContent=category==='flowers'?`${flowers.length} 种 · ${specimens.length} 款`:`${vessels.length} 款花器`;
 $('#material-grid').innerHTML=materials.map(a=>{const sample=category==='flowers'?specimenFor(a.id):a;return `<button class="material-card ${category==='vessels'&&a.id===state.vessel?'active':''}" data-material="${a.id}" aria-label="${category==='flowers'?'挑选':'选择'}${a.name}"><span class="add-mark">${category==='flowers'?'+':''}</span><img src="${assetPath(sample.id)}" alt="${a.name}" draggable="false" loading="lazy"><strong>${a.shortName||a.name}</strong><small>${category==='flowers'?a.variants+' 款可选':a.color}</small></button>`}).join('');
 $('#material-grid').onclick=e=>{const b=e.target.closest('[data-material]');if(!b)return;const type=b.dataset.material;if(category==='vessels'){if(state.vessel===type)return;checkpoint();const from=vesselGeometry(assetById[state.vessel]).insertion,to=vesselGeometry(assetById[type]).insertion;state.items.forEach(i=>{i.x=clamp(i.x+to[0]-from[0],5,95);i.y=clamp(i.y+to[1]-from[1],15,95)});state.vessel=type;renderStage();renderMaterials();persist();toast(`已换成${assetById[type].name}`)}else variantPicker(type)};
}
$$('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;$$('[data-category]').forEach(t=>t.setAttribute('aria-selected',String(t===b)));renderMaterials()});
$$('[data-vessel-group]').forEach(b=>b.onclick=()=>{vesselFilter=b.dataset.vesselGroup;$$('[data-vessel-group]').forEach(t=>t.classList.toggle('active',t===b));renderMaterials()});
$$('[data-family-group]').forEach(b=>b.onclick=()=>{familyFilter=b.dataset.familyGroup;$$('[data-family-group]').forEach(t=>t.classList.toggle('active',t===b));renderMaterials()});
function pointerStage(e){const r=$('#stage').getBoundingClientRect();return [(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height]}
function selectItem(id){selected=id;$$('.stem').forEach(n=>{const on=n.dataset.id===id;n.classList.toggle('selected',on);n.setAttribute('aria-pressed',String(on))});renderSelection()}
function renderLayerList(){
 const list=$('#layer-list');if(!list)return;
 const frontFirst=[...state.items].reverse();
 list.innerHTML=frontFirst.length?frontFirst.map((item,index)=>{const a=assetById[item.type];return `<div class="layer-row ${item.id===selected?'active':''}" data-layer-id="${item.id}" draggable="true"><span class="layer-grip" aria-hidden="true">⠿</span><button class="layer-select" data-layer-select="${item.id}" aria-label="选择${esc(a.name)}"><img src="${assetPath(item.type)}" alt=""><span><strong>${esc(a.name)}</strong><small>${index===0?'最前层':index===frontFirst.length-1?'最后层':`第 ${index+1} 层`}</small></span></button><span class="layer-step"><button data-layer-shift="front" aria-label="将${esc(a.name)}上移一层" ${index===0?'disabled':''}>↑</button><button data-layer-shift="back" aria-label="将${esc(a.name)}下移一层" ${index===frontFirst.length-1?'disabled':''}>↓</button></span></div>`}).join(''):'<div class="layer-empty">先添入花材，再安排层次。</div>';
}
function closeLayerMenu(){const menu=$('#layer-menu');if(menu.hidden)return;menu.hidden=true;$('#layers-tool').setAttribute('aria-expanded','false');layerDragId=null}
function openLayerMenu(clientX,clientY){
 const menu=$('#layer-menu'),stage=$('#stage'),rect=stage.getBoundingClientRect();setEditMode('move');menu.hidden=false;$('#layers-tool').setAttribute('aria-expanded','true');renderLayerList();
 const width=menu.offsetWidth||240,height=menu.offsetHeight||300;const x=Number.isFinite(clientX)?clientX-rect.left:rect.width-width-14;const y=Number.isFinite(clientY)?clientY-rect.top:54;menu.style.left=clamp(x,10,Math.max(10,rect.width-width-10))+'px';menu.style.top=clamp(y,10,Math.max(10,rect.height-height-10))+'px';
}
function shiftLayer(id,direction){
 const index=state.items.findIndex(i=>i.id===id),next=index+(direction==='front'?1:-1);if(index<0||next<0||next>=state.items.length)return;checkpoint();[state.items[index],state.items[next]]=[state.items[next],state.items[index]];selected=id;renderStage();persist();toast(direction==='front'?'已向前移动一层':'已向后移动一层');
}
function applyLayerDrop(id,targetId,after){
 if(!id||id===targetId)return;const frontFirst=[...state.items].reverse(),dragged=frontFirst.find(i=>i.id===id);if(!dragged)return;const without=frontFirst.filter(i=>i.id!==id),targetIndex=without.findIndex(i=>i.id===targetId);if(targetIndex<0)return;checkpoint();without.splice(targetIndex+(after?1:0),0,dragged);state.items=without.reverse();selected=id;renderStage();persist();toast('花材层次已调整');
}
$('#layer-list').addEventListener('click',e=>{const row=e.target.closest('[data-layer-id]');if(!row)return;const shift=e.target.closest('[data-layer-shift]');if(shift){shiftLayer(row.dataset.layerId,shift.dataset.layerShift);return}if(e.target.closest('[data-layer-select]')){selectItem(row.dataset.layerId);renderLayerList()}});
