function help(){openModal(`<h2>给自己一刻，慢慢插花。</h2><div class="step-list"><div><span class="step-number">01</span><p><strong>选花，落枝。</strong><br>点选左侧花材和花器。挑选同种花的自然花色与姿态，并决定新花材放在最前层或最后层。拖动调整位置；右键画布或点击图层按钮，可以拖动花材改变前后顺序。花材大小和枝梗长度可分别调整；圈选剪枝会真正去掉圈内的枝叶，细部擦除适合修小叶片。</p></div><div><span class="step-number">02</span><p><strong>写下你的意境。</strong><br>选择光与景，留下一句话。默认「自然重构」会让枝条重新长得自然，也可选择更大胆或更贴近布局的生成方式。下载创作包，在 ChatGPT 的图片创作或 GPT Image 中上传 draft.png，再粘贴 prompt.txt。</p></div><div><span class="step-number">03</span><p><strong>从草稿，到作品。</strong><br>把生成的图片导入「我的作品」，下载分享卡或使用设备分享。网页本身不直接调用付费生成服务。</p></div></div><p class="file-note">键盘也能创作：选中枝条后，方向键微调，Shift + 方向键大幅移动，Delete 删除。草稿与成品保存在当前浏览器，导出文件可以备份。</p><div class="modal-actions"><button class="button dark" id="help-done">开始这一枝</button><button class="button outline" id="help-import">导入草稿文件</button></div>`);$('#help-done').onclick=()=>$('#modal').close();$('#help-import').onclick=()=>$('#draft-upload').click()}
$('#help-button').onclick=help;
function sources(){openModal(`<h2>从自然取材，从花道取意。</h2><p>花间以自由创作练习为出发点，不为作品打分，也不将简化的构图方法当作流派规范。</p><h3>花道参考</h3><div class="source-list"><a href="https://chs.ikenobo.jp/about/style.html" target="_blank" rel="noopener noreferrer">池坊 · 花道的三种样式 ↗</a><br><a href="https://www.sogetsu.or.jp/e/begin/" target="_blank" rel="noopener noreferrer">草月 · 自由表达与学习 ↗</a></div><p>池坊的自由花重视草木的形状与质感；草月鼓励创作者表达自己的想法。这里的留白、方向和疏密提示，是游戏中的创作建议。</p><h3>素材说明</h3><p>花枝与自然花色、姿态素材使用 GPT Image 原创生成，植物为艺术化素材，不作为植物识别依据。新增花器使用 GPT Image 原创生成，保留各自真实风格的釉色与轮廓；原有两只花器来自 <a href="https://purepng.com/photo/18638/objects-vase" target="_blank" rel="noopener noreferrer">PurePNG / PNGStock</a>，来源页标注 CC0，已拆分裁切。灵感摄影为 Rémi Jouan 的 <a href="https://commons.wikimedia.org/wiki/File:Ikebana_International_Paris_2019_(01).JPG" target="_blank" rel="noopener noreferrer">Ikebana International Paris 2019 (01)</a>，依据 <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a> 使用，已缩小尺寸，未修改内容。</p><p class="file-note">资料整理：2026 年 9 月。你的作品由你导出和分享；本工房不自动公开上传图片。</p>`,'REFERENCES & MATERIALS')}
$('#sources-button').onclick=sources;
async function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('图片暂时无法载入，请稍后重试'));img.src=src})}
const imageTasks=new Map();
function ensureAsset(id){if(images[id])return Promise.resolve(images[id]);if(!imageTasks.has(id)){imageTasks.set(id,loadImage(assetPath(id)).then(img=>{images[id]=img;return img}).catch(err=>{imageTasks.delete(id);throw err}))}return imageTasks.get(id)}
